def isqrt(n):
    """Integer square root using only integer arithmetic (Newton's method)."""
    if n < 0:
        raise ValueError("square root of negative number")
    if n == 0:
        return 0
    x = n
    y = (x + 1) // 2
    while y < x:
        x = y
        y = (x + n // x) // 2
    return x

