def wrap(text, width):
    words = text.split()
    if not words:
        return []
    lines = []
    i = 0
    while i < len(words):
        line = []
        width_used = 0
        while i < len(words):
            w = words[i]
            if width_used == 0:
                line.append(w)
                width_used = len(w)
                i += 1
            else:
                if width_used + 1 + len(w) <= width:
                    line.append(w)
                    width_used += 1 + len(w)
                    i += 1
                else:
                    break
        lines.append(' '.join(line))
    return lines


def dedent(text):
    lines = text.split('\n')
    leads = []
    for line in lines:
        i = 0
        while i < len(line) and line[i] == ' ':
            i += 1
        leads.append(i)
    min_indent = min([l for l in leads if l > 0] or [0])
    new_lines = []
    for line in lines:
        if min_indent > 0:
            new_lines.append(line[min_indent:])
        else:
            new_lines.append(line)
    return '\n'.join(new_lines)


